function MenuWorkspacePublishDialog({busy,disabled,error,onConfirm,onClose,title,text}) {
 const ref=useRef(null),closeRef=useRef(onClose);closeRef.current=onClose;
 useEffect(()=>{const dialog=ref.current,previous=window.document.activeElement;dialog?.showModal();return()=>{dialog?.close();if(previous?.isConnected)previous.focus();};},[]);
 const tokens=window.TakoMenuMotion,style={'--mw-motion-duration':`${tokens?.durationMs?.surface||340}ms`,'--mw-motion-ease':`cubic-bezier(${(tokens?.easing?.out||[.22,1,.36,1]).join(',')})`};
 return ReactDOM.createPortal(<dialog ref={ref} className="mw-publish-dialog" style={style} aria-label="Riepilogo pubblicazione" aria-labelledby="mw-publish-title" aria-describedby="mw-publish-description" aria-busy={busy} onCancel={e=>{e.preventDefault();if(!busy)closeRef.current();}} onClick={e=>{if(e.target!==e.currentTarget||busy)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeRef.current();}}><h3 id="mw-publish-title">{title||'Pubblicare le modifiche?'}</h3><p id="mw-publish-description">{text||'Il menu digitale dei clienti verrà aggiornato.'}</p>{error&&<p className="mw-publish-error" role="alert">{error}</p>}<div className="mw-publish-actions"><Btn kind="soft" disabled={busy} onClick={onClose}>Annulla</Btn><Btn disabled={busy||disabled} onClick={onConfirm}>{busy?'Pubblicazione…':'Pubblica'}</Btn></div></dialog>,window.document.body);
}
/* Media query reattiva: il riquadro cambia forma (foglio dal basso ↔ pannello) anche quando la finestra viene ridimensionata. */
function MW_USE_MEDIA(query) {
 const [match,setMatch]=useState(()=>window.matchMedia(query).matches);
 useEffect(()=>{const media=window.matchMedia(query),update=()=>setMatch(media.matches);update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update);},[query]);
 return match;
}
const MW_PHOTO_TYPES=['image/jpeg','image/png','image/webp'];
const MW_HAS_FILES=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');
const MW_FIRST_FILE=e=>{const files=Array.from(e.dataTransfer?.files||[]);return files.find(f=>f.type.startsWith('image/'))||files[0]||null;};
/* Zona foto del riquadro «Modifica piatto»: trascina o «Carica» (Invio/Spazio), anteprima con × per togliere la foto, Annulla durante il caricamento. */
