function MenuWorkspaceLanguages({adapter,document,menu,mutate,dirty,onPreview}) {const [language,setLanguage]=useState(document.languages?.[0]||'en');const [catalogs,setCatalogs]=useState(null);useEffect(()=>{adapter.listCatalogs().then(setCatalogs).catch(()=>{});},[adapter]);return <Card><h3>Traduzioni</h3><MenuWorkspaceTranslationStatus document={document}/><MenuWorkspaceTranslate adapter={adapter} document={document} dirty={dirty} onPreview={onPreview}/><MenuWorkspaceField label="Lingue abilitate (codici separati da virgola)" value={(document.languages||[]).join(', ')} onChange={v=>mutate(d=>{d.languages=v.split(',').map(l=>l.trim()).filter(Boolean);})}/><label className="mw-field">Lingua originale<select value={document.defaultLanguage} onChange={e=>mutate(d=>{d.defaultLanguage=e.target.value;})}>{document.languages.map(l=><option key={l} value={l}>{l}</option>)}</select></label><select aria-label="Lingua da modificare" value={language} onChange={e=>setLanguage(e.target.value)}>{(document.languages||[]).map(l=><option key={l} value={l}>{l}</option>)}</select>{catalogs&&<section><h4>Etichette e legende alimentari</h4>{[{id:"allergens",label:"Titolo allergeni"},...(catalogs.allergens||[]),...(catalogs.traits||[]),...(catalogs.additives||[])].map(c=><MenuWorkspaceField key={c.id} label={c.label} value={document.foodTranslations?.[language]?.[c.id]||""} onChange={text=>mutate(d=>{d.foodTranslations={...d.foodTranslations,[language]:{...d.foodTranslations?.[language],[c.id]:text}};})}/>)}</section>}{menu&&<><MenuWorkspaceField label={`Nome menu: ${menu.name}`} value={menu.translations?.[language]?.name||''} onChange={name=>mutate(d=>{const m=d.menus.find(m=>m.id===menu.id);m.translations={...m.translations,[language]:{...m.translations?.[language],name}};})}/><MenuWorkspaceField label="Descrizione menu tradotta" value={menu.translations?.[language]?.description||''} onChange={description=>mutate(d=>{const m=d.menus.find(m=>m.id===menu.id);m.translations={...m.translations,[language]:{...m.translations?.[language],description}};})}/></>}{menu?.sections.map(section=><section key={section.id}><MenuWorkspaceField label={`Sottomenu: ${section.name}`} value={section.translations?.[language]?.name||''} onChange={name=>mutate(d=>{const s=d.menus.find(m=>m.id===menu.id).sections.find(s=>s.id===section.id);s.translations={...s.translations,[language]:{...s.translations?.[language],name}};})}/><MenuWorkspaceField label="Descrizione del sottomenu tradotta" value={section.translations?.[language]?.description||''} onChange={description=>mutate(d=>{const s=d.menus.find(m=>m.id===menu.id).sections.find(s=>s.id===section.id);s.translations={...s.translations,[language]:{...s.translations?.[language],description}};})}/>{section.items.map(item=><div key={item.id}><MenuWorkspaceField label={`Nome: ${item.name}`} value={item.translations?.[language]?.name||''} onChange={name=>mutate(d=>{const i=d.menus.find(m=>m.id===menu.id).sections.find(s=>s.id===section.id).items.find(i=>i.id===item.id);i.translations={...i.translations,[language]:{...i.translations?.[language],name}};})}/><MenuWorkspaceField label="Descrizione tradotta" value={item.translations?.[language]?.description||''} onChange={description=>mutate(d=>{const i=d.menus.find(m=>m.id===menu.id).sections.find(s=>s.id===section.id).items.find(i=>i.id===item.id);i.translations={...i.translations,[language]:{...i.translations?.[language],description}};})}/></div>)}</section>)}</Card>;}
