function MenuWorkspaceSchedule({value,onChange}) {
 const schedule=value||{enabled:false,timezone:'Europe/Rome',windows:[],from:null,until:null};
 const set=(key,v)=>onChange({...schedule,[key]:v});
 return <section><h4>Disponibilità programmata</h4><label className="mw-check"><input type="checkbox" checked={schedule.enabled} onChange={e=>set('enabled',e.target.checked)}/>Limita a giorni e orari</label>{schedule.enabled&&<><MenuWorkspaceField label="Fuso orario" value={schedule.timezone} onChange={v=>set('timezone',v)}/><MenuWorkspaceField label="Dal giorno" type="date" value={schedule.from||''} onChange={v=>set('from',v||null)}/><MenuWorkspaceField label="Fino al giorno" type="date" value={schedule.until||''} onChange={v=>set('until',v||null)}/>{schedule.windows.map((w,index)=><div key={index}><div className="mw-row">{['Dom','Lun','Mar','Mer','Gio','Ven','Sab'].map((day,n)=><label key={day}><input type="checkbox" checked={w.weekdays.includes(n)} onChange={e=>set('windows',schedule.windows.map((x,i)=>i===index?{...x,weekdays:e.target.checked?[...x.weekdays,n]:x.weekdays.filter(d=>d!==n)}:x))}/>{day}</label>)}</div><div className="mw-row"><MenuWorkspaceField label="Dalle" type="time" value={w.start} onChange={start=>set('windows',schedule.windows.map((x,i)=>i===index?{...x,start}:x))}/><MenuWorkspaceField label="Alle" type="time" value={w.end} onChange={end=>set('windows',schedule.windows.map((x,i)=>i===index?{...x,end}:x))}/><Btn kind="soft" size="sm" onClick={()=>set('windows',schedule.windows.filter((_,i)=>i!==index))}>Rimuovi intervallo</Btn></div></div>)}<Btn size="sm" kind="soft" onClick={()=>set('windows',[...schedule.windows,{weekdays:[1,2,3,4,5,6,0],start:'12:00',end:'15:00'}])}>Aggiungi intervallo</Btn><p>Se l'orario finale precede quello iniziale, l'intervallo termina il giorno successivo.</p></>}</section>;
}
