const MW_DOCUMENT=doc=>{const {revision,publishedRevision,capabilities,...data}=doc;return data;};
// Lettura del workspace avviata subito dopo il cambio locale (vedi 20-agency-dashboard): usata una sola volta, entro 5 s, mai dopo una scrittura.
window.takoWarmMenuWorkspace=()=>{window.__mwWarm={at:Date.now(),promise:fetch('/api/menu-workspace',{credentials:'include',headers:{'Content-Type':'application/json'}}).then(async r=>r.ok?await r.json():null).catch(()=>null)}};
const MW_REQUEST=async(path,method='GET',body)=>{
 const warm=window.__mwWarm;window.__mwWarm=null;
 if(path===''&&method==='GET'&&warm&&Date.now()-warm.at<5000){const result=await warm.promise;if(result?.data)return result;}
 const response=await fetch('/api/menu-workspace'+path,{method,credentials:'include',headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});
 const result=await response.json().catch(()=>null);
 if(!response.ok){const error=new Error(result?.error?.message||'Operazione menu non riuscita');error.status=response.status;throw error;}
 return result;
};
// Stesso ordine delle chiavi di Postgres jsonb (prima le più corte in byte UTF-8, poi confronto binario): il documento del PUT diventa identico a quello che la GET rileggerebbe.
const MW_UTF8=k=>unescape(encodeURIComponent(k)),MW_KEY_ORDER=(a,b)=>{const x=MW_UTF8(a),y=MW_UTF8(b);return x.length!==y.length?x.length-y.length:x<y?-1:x>y?1:0;};
const MW_JSONB_ORDER=value=>Array.isArray(value)?value.map(MW_JSONB_ORDER):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort(MW_KEY_ORDER).map(k=>[k,MW_JSONB_ORDER(value[k])])):value;
const MW_NORMALIZE=result=>(window.__takoMenuEditorFlag=result.dashboardEditor===true,{...result.data,revision:result.revision,publishedRevision:result.publishedRevision,capabilities:['owner','menu_editor'].includes(window.__takoRole)?['content','style','pdf']:[]});
