 if(source.kind==='menu'){const from=doc.menus.findIndex(m=>m.id===source.id),to=doc.menus.findIndex(m=>m.id===target.id);if(from<0||to<0)return false;const [entry]=doc.menus.splice(from,1);doc.menus.splice(doc.menus.findIndex(m=>m.id===target.id)+(target.after?1:0),0,entry);return true;}
