function MenuWorkspaceActionIcon({kind}){const paths={chat:'M5 5h14v11H9l-4 4V5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4',history:'M4 8a8 8 0 1 1-1 6M4 3v5h5M12 7v5l3 2',layout:'M4 4h16v16H4V4m0 5h16M14 9v11',save:'M5 4h12l3 3v13H4V4h1m3 0v6h8V4M8 20v-6h8v6'};return <svg width="28" height="28" viewBox="0 0 24 24" aria-hidden fill="none"><path d={paths[kind]} stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>;}

function MenuWorkspaceMobilePreview({kind,adapter,document,menuId,language,dirty,onClose}){
 const modal=useRef(null),frame=useRef(null),close=useRef(onClose);close.current=onClose;
 const [blob,setBlob]=useState(null),[error,setError]=useState(''),[retry,setRetry]=useState(0);
 useEffect(()=>{const previous=window.document.activeElement;modal.current.showModal();return()=>{modal.current?.close();previous?.isConnected&&previous.focus();};},[]);
 useEffect(()=>{if(kind!=='pdf')return;let alive=true;setError('');setBlob(null);if(dirty){setError('Salva la bozza per visualizzare il PDF aggiornato.');return;}adapter.renderPdf({menuIds:[menuId],language:language||undefined,preview:true}).then(value=>{if(alive)setBlob(value)}).catch(e=>{if(alive)setError(e.message||'Impossibile aprire il PDF')});return()=>{alive=false};},[kind,menuId,language,dirty,retry]);
 useEffect(()=>{const ready=e=>{if(e.origin===location.origin&&e.source===frame.current?.contentWindow&&e.data?.type==='tako-menu-preview-ready')e.source.postMessage({type:'tako-menu-preview',document,menuId,language:language||undefined},location.origin)};window.addEventListener('message',ready);return()=>window.removeEventListener('message',ready)},[document,menuId,language]);
 return ReactDOM.createPortal(<dialog ref={modal} className="mw-glass-preview" aria-label={kind==='menu'?'Anteprima menu mobile':'Anteprima PDF mobile'} onCancel={e=>{e.preventDefault();close.current()}}><header><strong>{kind==='menu'?'Menu cliente':'Menu PDF'}</strong><button type="button" aria-label="Chiudi anteprima" onClick={onClose}>×</button></header><div className="mw-glass-preview-content">{kind==='menu'?<iframe ref={frame} title="Menu cliente a schermo intero" src={'/menu-preview/'+menuId} onLoad={e=>e.currentTarget.contentWindow?.postMessage({type:'tako-menu-preview',document,menuId,language:language||undefined},location.origin)}/>:error?<div className="mw-pdf-retry"><p role="alert">{error}</p>{!dirty&&<Btn kind="soft" onClick={()=>setRetry(v=>v+1)}>Riprova</Btn>}</div>:blob?<><MenuWorkspacePdfViewer blob={blob}/><div className="mw-pdf-mobile-actions"><Btn onClick={()=>MW_SAVE_PDF(blob)}>Scarica PDF</Btn></div><p className="mw-swipe-hint">Scorri a destra o sinistra per cambiare pagina</p></>:<TakoLoading variant="page" label="Preparazione PDF…"/>}</div></dialog>,window.document.body);
}

const MW_PDF_REQUESTS=new Map();
function MW_RENDER_PDF(body){
 const key=String(window.__takoRestaurantId)+'|'+JSON.stringify(body);if(MW_PDF_REQUESTS.has(key))return MW_PDF_REQUESTS.get(key);
 const request=(async()=>{for(let attempt=0;attempt<3;attempt++){
  let response;try{response=await fetch('/api/menu-workspace/pdf',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(60000)});}catch(e){if(attempt<2){await new Promise(resolve=>setTimeout(resolve,500*(attempt+1)));continue;}throw new Error('Connessione interrotta durante la generazione. Riprova.');}
  if(response.ok){const blob=await response.blob();if(blob.size<5||!blob.type.includes('pdf'))throw new Error('Il server non ha restituito un PDF valido. Riprova.');return blob;}
  let detail={};try{detail=await response.json()}catch{}
  // 546 = risorse dell'edge esaurite (avvio a freddo/memoria): transitorio come 503, si riprova.
  if([429,502,503,504,546].includes(response.status)&&attempt<2){await new Promise(resolve=>setTimeout(resolve,Math.min(3000,Math.max(response.status===546?1500:500,Number(response.headers.get('Retry-After')||0)*1000))*(attempt+1)));continue;}
  if(response.status===401)throw new Error('La sessione è scaduta. Accedi nuovamente per aprire il PDF.');
  if(response.status===404)throw new Error('Questo menu non è disponibile nel locale selezionato. Riapri il locale e riprova.');
  throw new Error(detail.error?.message||(typeof detail.message==='string'?detail.message:'')||(response.status===546?'Il server è occupato: il PDF non è stato generato. Riprova tra qualche secondo.':'Il PDF non è disponibile al momento. Riprova.'));
 }} )();MW_PDF_REQUESTS.set(key,request);request.then(()=>MW_PDF_REQUESTS.delete(key),()=>MW_PDF_REQUESTS.delete(key));return request;
}
